from taf.collectors.core.entities.managed_vdu_connection import ManagedVduConnection
from .factory import ReusableFactory


class ManagedVduConnectionFactory(ReusableFactory):
    """
    Factory for managed vDU connection.
    """

    _product_class = ManagedVduConnection
    _mandatory_parameters = {"vdu_connection_params"}
    _existing_product_objects = {}

    @staticmethod
    def _create_unique_key (resulting_arguments):
        reuse = resulting_arguments["vdu_connection_params"].get("reuse", True)
        unique_key = tuple(
            sorted(
                (k, d[k])
                for k in ("user", "host", "port", "release")
                if k in (d := resulting_arguments["vdu_connection_params"])))
        return unique_key, reuse
